fn ensure_gen_dir(repo_root: &Path) -> Result<(), String> {
    let d = repo_root.join("infra/gen/chief");
    fs::create_dir_all(&d).map_err(|e| e.to_string())
}

/// Patch `infra/gen/chief/docs_project.cue` and PlantUML assets from `infra/docs.rice`.
pub fn apply_docs_overlay(repo_root: &Path, project_slug: &str) -> Result<(), String> {
    ensure_gen_dir(repo_root)?;
    let rice_path = repo_root
        .join("custom")
        .join(project_slug)
        .join("infra/docs.rice");
    let out = if rice_path.is_file() {
        let bowl_path = repo_root.join("custom").join(project_slug).join("bowl");
        let bowl_src = fs::read_to_string(&bowl_path).map_err(|e| e.to_string())?;
        let bowl_infra = crate::infra_rice::parse_bowl_infra_package(&bowl_src)?;
        let rice_src = fs::read_to_string(&rice_path).map_err(|e| e.to_string())?;
        let rice_import = crate::infra_rice::parse_infra_use_line(&rice_src)?;
        crate::infra_rice::validate_infra_rice_import(
            &bowl_infra,
            &rice_import,
            crate::infra_rice::FACET_DOCS,
        )?;
        let cfg = crate::docs_rice::parse_docs_rice(&rice_src)?;
        crate::docs_rice::write_diagram_assets(repo_root, &cfg)?;
        crate::docs_rice::render_project_cue(&cfg)
    } else {
        crate::docs_rice::render_disabled_stub()
    };
    fs::write(
        repo_root.join("infra/gen/chief/docs_project.cue"),
        out,
    )
    .map_err(|e| e.to_string())?;
    Ok(())
}

/// Patch `infra/gen/chief/frontend_project.cue` and `frontend/lib/generated/rice_config.dart`.
pub fn apply_frontend_overlay(repo_root: &Path, project_slug: &str) -> Result<(), String> {
    ensure_gen_dir(repo_root)?;
    let site_rice = repo_root
        .join("custom")
        .join(project_slug)
        .join("frontend/site.rice");
    if !site_rice.is_file() {
        let stub = crate::frontend_rice::render_disabled_stub();
        fs::write(
            repo_root.join("infra/gen/chief/frontend_project.cue"),
            stub,
        )
        .map_err(|e| e.to_string())?;
        return Ok(());
    }
    let bowl_path = repo_root.join("custom").join(project_slug).join("bowl");
    let bowl_src = fs::read_to_string(&bowl_path).map_err(|e| e.to_string())?;
    let bowl_infra = crate::infra_rice::parse_bowl_infra_package(&bowl_src)?;
    let rice_src = fs::read_to_string(&site_rice).map_err(|e| e.to_string())?;
    let rice_import = crate::infra_rice::parse_infra_use_line(&rice_src)?;
    crate::infra_rice::validate_infra_rice_import(
        &bowl_infra,
        &rice_import,
        crate::infra_rice::FACET_FRONTEND,
    )?;
    let cfg = crate::frontend_rice::parse_frontend_rice(&rice_src)?;
    let out = crate::frontend_rice::render_project_cue(&cfg);
    fs::write(
        repo_root.join("infra/gen/chief/frontend_project.cue"),
        out,
    )
    .map_err(|e| e.to_string())?;
    let project_dir = repo_root.join("custom").join(project_slug);
    crate::frontend_rice::write_dart_config(&project_dir, &cfg)?;
    Ok(())
}

/// Resolve CHIEF project slug — requires `CHIEF_PROJECT` for overlay apply / gen.
pub fn chief_project_slug(_repo_root: &Path) -> Option<String> {
    std::env::var("CHIEF_PROJECT")
        .ok()
        .map(|p| p.trim().to_string())
        .filter(|p| !p.is_empty())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_two_lets() {
        let s = r#"
# c
let rice_domain = "a.example"
let rice_environment = "dev";
"#;
        let v = parse_let_string_bindings(s).unwrap();
        assert_eq!(
            v,
            vec![
                ("rice_domain".into(), "a.example".into()),
                ("rice_environment".into(), "dev".into()),
            ]
        );
    }

    #[test]
    fn parse_bowl_project_name() {
        let s = "[project]\nname = \"code-rice.com\"\n";
        assert_eq!(parse_bowl_name(s).unwrap(), "code-rice.com");
    }

    #[test]
    fn parse_bowl_requires_infra_package() {
        let s = "[project]\nname = \"egos.app\"\n";
        assert!(crate::infra_rice::parse_bowl_infra_package(s).is_err());
    }

    #[test]
    fn validate_rejects_unknown_rice_key() {
        let allowed: HashSet<_> = terraform_rice_variable_names()
            .into_iter()
            .collect();
        let bindings = vec![("rice_not_a_var".into(), "x".into())];
        let e = validate_terraform_overlay(&bindings, &allowed);
        assert!(e.iter().any(|m| m.contains("not a MASON")));
    }
}
